mapper.sql:
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.State = #{params.state}


    and INSTR(mn.Ifr_File_Name,#{params.ifrFileName})


    and INSTR(mn.Ifr_Reply_Code,#{params.ifrReplyCode})


    and INSTR(mn.Ifr_Create_Uname,#{params.ifrCreateUname})

mapper.select:
select
(select count(1) from Inv_Project_Plan ipp where ipp.Ifr_Id = mn.Ifr_Id) as ippCount,
mn.*
from Inv_Fund_Release mn


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Ifr_Create_Time desc
    

limit #{params.start},#{params.size}
